from pathlib import Path
import json,numpy as np
R=Path(__file__).resolve().parents[2];H=R/'research/round99';B=R/'crossplatform/round99';S=H/'scores_attempt001';rd=lambda p:json.loads(Path(p).read_text())
def main():
 assert rd(H/'SCALAR_AUDIT.json')['state'].startswith('PASS_');rows=rd(S/'ALL_METHOD_ROWS.json');agg=rd(S/'AGGREGATE_ROWS.json');pairs=rd(S/'ALL_PAIRED_ROWS.json');macro={x['arm']:x for x in agg if x['group']=='all_six_equal'};v=lambda k:macro[k]['mIoU_percent'];decision={'primary':'joint3_FC','primary_mIoU_percent':v('joint3_FC'),'gains_pp':{k:v('joint3_FC')-v(k) for k in ['prepared_frozen','lm_FC','direct_FC','direct_four','joint3_shuffle_FC']},'heldoutC_vs_oneview_pp':v('joint3_C')-v('lm_C'),'heldoutC_vs_frozen_pp':v('joint3_C')-v('frozen_C'),'F_vs_oneview_pp':v('joint3_F')-v('lm_F'),'F_vs_direct_pp':v('joint3_F')-v('binding_direct'),'n':768,'historically_exposed_development':True,'FINAL_access':False,'new_experts':False,'source_training':False,'no_secondary_promotion':True,'robust_adoption':False}
 (H/'DECISION.json').write_text(json.dumps(decision,indent=2)+'\n');lines=['# R99 — 固定G，只改变拟合视图数','','本轮在R98断点分析后，只把同一末端匹配投影的监督由完整F扩展为F及原有两个互补遮挡；G、原始A256、source准备权重、参数范围18,496、十次LM与每次六次阻尼试探均保留。没有引入外部专家、源域重训练或新目标身份标签。主方法预先固定joint3_FC，未拟合C在全部拟合完成后才读取。','','## 已有全量证据的断点','','以下不是新预测成绩，是对已审核R98全部18,620条的单因素重组。','', '| 因素 | 六方向等权Δ mIoU pp | 改善/恶化 |','|---|---:|---:|']
 for x in rd(H/'COMPONENT_MACRO.json'):lines.append(f"| {x['component']} | {x['gain_pp_equal_six']:+.6f} | {x['better']}/{x['worse']} |")
 lines+=['','C单独降低冻结模型成绩；把C加入最终平均本身也有损失。不能将原完整配方的净损失全部称为参数更新失败。另一方面，F上G直接读出略好于参数拟合，说明单视图监督的利用仍有限。以上对比不证明mask中的RGB或LiDAR哪一项是根因。','','## 新实验：六方向固定开发清单','','每个目标平台按场景轮转和ID哈希固定128条，各入向source共用同一128条，合计768有向任务。Waymo覆盖93场景，Drone2、Quad3；这是已暴露开发数据，不能称独立确认。所有负例、UNKNOWN、无变化均保留。','', '| 方向 | 冻结 | 旧单视图LM FC | 同信息直接FC | 直接四视图 | 新三视图LM FC | 打乱监督FC |','|---|---:|---:|---:|---:|---:|---:|']
 for src in ['waymo','drone','quad']:
  for tgt in ['waymo','drone','quad']:
   if src==tgt:continue
   z={x['arm']:x for x in rows if x['source']==src and x['target']==tgt};lines.append('| '+src+'→'+tgt+' | '+' | '.join(f"{z[k]['mIoU_percent']:.6f}" for k in ['prepared_frozen','lm_FC','direct_FC','direct_four','joint3_FC','joint3_shuffle_FC'])+' |')
 lines+=['','## 平台、端点与全部负比较','','| 范围 | 方法 | mIoU % | Acc25 % | Acc50 % |','|---|---|---:|---:|---:|']
 for x in agg:lines.append(f"| {x['group']} | {x['arm']} | {x['mIoU_percent']:.6f} | {x['Acc25_percent']:.6f} | {x['Acc50_percent']:.6f} |")
 lines+=['','| 方向 | 方法 | 对照 | Δ pp | 改善/恶化/不变 |','|---|---|---|---:|---:|']
 for x in pairs:lines.append(f"| {x['source']}→{x['target']} | {x['method']} | {x['control']} | {x['gain_pp']:+.6f} | {x['better']}/{x['worse']}/{x['same']} |")
 lines+=['','## 技术核验与good/failure案例','','三source六个真实工程样本退回单视图时，与原LM最终权重最大误差均为零。正式768条全部封存后，独立重放全部拟合端点、目标误差和接受条件，并在六个真实样本重算原生三视图特征及拟合权重。显式Jacobian与autograd比较，显式J·Jᵀ与分块Gram比较，另用通用3D交核验主结果IoU；旧对照与R98原逐例值保持一致。','','从全量R98每方向每因素的正负变化中固定两条极值和一条中位变化样本，形成可追溯案例列表。另生成12页原图、投影、BEV和候选排名私有图册；实际人工式本地视觉复核仅两页，不宣称全部完成身份审核。复核发现一个纠错中F已纠正而C仍错，平均仍正确；另一个误改中F/C各自Top1均未改变，但概率间隔改变后使FC从正确行人候选转向另一候选。因此Top1是否改变本身不足以描述平均读出的损伤。身份不确定保持未知，案例不参与适应或逐例规则。','','图册原句、媒体、框坐标、query索引和特征均不公开。可视化首尝试将非Waymo的空suffix转整数导致异常，尚无页面或方法结果受影响；修复仅为可视化坐标参数默认0，保留失败尝试，不改科学预测。','','## 本轮裁决','',f"固定主端点={v('joint3_FC'):.6f}%，相对旧单视图LM FC {decision['gains_pp']['lm_FC']:+.6f}pp，相对冻结{decision['gains_pp']['prepared_frozen']:+.6f}pp，相对同信息直接FC {decision['gains_pp']['direct_FC']:+.6f}pp，相对打乱监督{decision['gains_pp']['joint3_shuffle_FC']:+.6f}pp。未拟合C相对旧单视图C {decision['heldoutC_vs_oneview_pp']:+.6f}pp，相对冻结C {decision['heldoutC_vs_frozen_pp']:+.6f}pp。F相对直接证据{decision['F_vs_direct_pp']:+.6f}pp。不会将更高的次要端点事后升级为原主方法。",'', '本轮只更新拟合视图数这一配方的证据。优化误差下降、更多非零步、局部好图均不能代替总体任务收益。夜间目标仍进行，后续实验必须根据这些差异锁定新假设，保留无外部专家、固定候选和同信息控制；截止2026-11-16北京时间09:30后不启动新模型、训练或评分。']
 lines+=['',f"开发信号说明：主端点对旧LM FC仅7条IoU改善、3条恶化，其余758条不变；相对冻结22条改善、19条恶化。尽管六个方向相对冻结均为正，样本改变量仍少，必须不改参数扩展全量才能判断。该场景均衡小清单上原始3EED为{v('original_source'):.6f}%，仍高于当前准备后系统；不能把适应相对自身冻结的增量称为整个系统已经超过原始3EED。下一步R100固定本算法和全部对照，原样扩展原18620清单，不按已看GT改方法。"]
 (H/'REPORT.md').write_text('\n'.join(lines)+'\n');print(decision)
